CREATE TABLE regions (region_code char(2) PRIMARY KEY, name varchar(80) NOT NULL UNIQUE);
CREATE TABLE regional_targets (region_code char(2) PRIMARY KEY REFERENCES regions(region_code), monthly_target numeric(12,2) NOT NULL CHECK (monthly_target >= 0));
CREATE TABLE warehouses (id integer PRIMARY KEY, region_code char(2) NOT NULL REFERENCES regions(region_code), name varchar(120) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, opens_at time NOT NULL);
CREATE TABLE categories (id integer PRIMARY KEY, name varchar(120) NOT NULL, parent_id integer REFERENCES categories(id), active boolean NOT NULL DEFAULT true, UNIQUE(parent_id, name));
CREATE TABLE suppliers (id integer PRIMARY KEY, name varchar(120) NOT NULL UNIQUE, country_code char(2) NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE customers (id uuid PRIMARY KEY, display_name varchar(120) NOT NULL, email varchar(254) NOT NULL UNIQUE, country_code char(2) NOT NULL, active boolean NOT NULL DEFAULT true, registered_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_addresses (id bigint PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), country_code char(2) NOT NULL, line1 text NOT NULL, line2 text, is_default boolean NOT NULL DEFAULT false, updated_at timestamp NOT NULL);
CREATE TABLE employees (id integer PRIMARY KEY, name varchar(120) NOT NULL, manager_id integer REFERENCES employees(id), hired_on date NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE products (id integer PRIMARY KEY, sku varchar(40) NOT NULL UNIQUE, name text NOT NULL, category_id integer NOT NULL REFERENCES categories(id), list_price numeric(12,2) NOT NULL CHECK (list_price >= 0), active boolean NOT NULL DEFAULT true, discontinued_at timestamp);
CREATE TABLE product_suppliers (product_id integer NOT NULL REFERENCES products(id), supplier_id integer NOT NULL REFERENCES suppliers(id), supplier_sku varchar(60) NOT NULL, PRIMARY KEY(product_id, supplier_id), UNIQUE(supplier_id, supplier_sku));
CREATE TABLE inventory (warehouse_id integer NOT NULL REFERENCES warehouses(id), product_id integer NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK (quantity >= 0), reorder_level integer NOT NULL DEFAULT 10 CHECK (reorder_level >= 0), PRIMARY KEY(warehouse_id, product_id));
CREATE TABLE orders (id bigint PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), shipping_address_id bigint REFERENCES customer_addresses(id), ordered_at timestamptz NOT NULL, status varchar(20) NOT NULL CHECK (status IN ('pending','paid','cancelled','refunded','delivered')), total_amount numeric(12,2) NOT NULL CHECK (total_amount >= 0));
CREATE TABLE order_items (id bigint PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id), product_id integer NOT NULL REFERENCES products(id), quantity smallint NOT NULL CHECK (quantity > 0), unit_price numeric(12,2) NOT NULL CHECK (unit_price >= 0), UNIQUE(order_id, product_id));
CREATE TABLE payments (id bigint PRIMARY KEY, order_id bigint REFERENCES orders(id), status varchar(20) NOT NULL CHECK (status IN ('pending','succeeded','failed','refunded')), amount numeric(12,2) NOT NULL CHECK (amount >= 0), currency char(3), paid_at timestamptz);
CREATE TABLE shipments (id bigint PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id), warehouse_id integer NOT NULL REFERENCES warehouses(id), status varchar(20) NOT NULL CHECK (status IN ('pending','shipped','delivered','late')), tracking_code varchar(60), scheduled_at timestamptz NOT NULL, delivered_at timestamptz);
CREATE TABLE reviews (id bigint PRIMARY KEY, customer_id uuid REFERENCES customers(id), product_id integer NOT NULL REFERENCES products(id), score smallint CHECK (score BETWEEN 1 AND 5), body text, reviewed_at timestamptz);
CREATE TABLE promotions (id integer PRIMARY KEY, code varchar(40) NOT NULL UNIQUE, starts_on date NOT NULL, ends_on date NOT NULL, CHECK (ends_on >= starts_on));
CREATE TABLE order_promotions (order_id bigint NOT NULL REFERENCES orders(id), promotion_id integer NOT NULL REFERENCES promotions(id), PRIMARY KEY(order_id, promotion_id));
